"""把同一份规则填入网站养护正文；阈值和剂量不在HTML里另存。"""
from html import escape
from care import RULES

def render(text):
    r=RULES;c=r['cycling'];d=r['doses'];l=r['limits']
    f=lambda n:f'{n:g}'
    feed=f'{20*d["feed_ml_per_l"]:.1f}';check=f'{20*d["check_ml_per_l"]:.1f}'
    daily=f'''<ol class="steps"><li>NH3高于{c['nh3_high']:g}：测稀释样，今天不加氯化铵水；按本页的稀释与换水说明处理。</li><li>NH3不是0：今天不加，继续供氧控温，明天再测。沙里发在这桶海水里读数偏低，仅供参考；补氨与检查以益尔可靠读数为依据。</li><li>NH3是0，NO2≤{c['no2_pass']:g}：开始{c['check_hours']}小时检查。</li><li>NH3是0，NO2介于{c['no2_pass']:g}与{c['no2_top']:g}之间：先等；连续{c['feed_wait_days']}天在这一档，补喂{feed}g氯化铵水。</li><li>NO2到{c['no2_top']:g}顶格：测稀释样，读数×{c['dilution_factor']}；折算原水低于{c['no2_feed_below']:g}，补喂{feed}g；达到{c['no2_feed_below']:g}或更高，继续等。稀释样也到顶，只能记作≥{c['no2_top']*c['dilution_factor']:g}。</li></ol>'''
    checks=f'''<ol class="steps"><li>NH3为0、NO2≤{c['no2_pass']:g}时，加{check}g氯化铵水（20L示例），记录加药时间。</li><li>满{c['check_hours']}小时，同次测益尔NH3和NO2：NH3为0、NO2≤{c['no2_pass']:g}，计通过一轮；未通过就回到每天判断，不叠加检查量。</li><li>连续通过{c['check_rounds']}轮才算养好。记录页自动计数要求在加药后{c['check_hours']}–{c['check_latest_hours']}小时复测；这段时间换水、加Prime或再次加氨，本轮不计。</li><li>通过后停加氯化铵水，水温调回{l['temperature_animals_green'][0]:g}–{l['temperature_animals_green'][1]:g}℃。测NO3：10或以下换约2L；25换约5L；50或100换一半，次日复测再决定。</li><li>接鱼前备同温同盐新水、透气防跳盖和躲避物，按<a href="guide-quar.html">检疫观察</a>接鱼；超过一周仍未接动物，按本页空喂规则维护菌床。</li></ol>'''
    animal=f'''<ul><li><b>0色：</b>照常观察。</li><li><b>高于0、低于{d['animal_nh3_half_change_at']:g}：</b>减喂、吸污，换三分之一水（20L示例约{20*d['animal_change_low']:.1f}L），次日复测。</li><li><b>{d['animal_nh3_half_change_at']:g}或更高：</b>减喂、吸污，换一半水（20L示例{20*d['animal_change_high']:g}L），换后Prime按整缸水量加{20*d['prime_ml_per_l']:g}mL。用药时先核兼容性。</li><li>加Prime后约{d['prime_interference_hours']}小时内，沙里发NH3读数会受干扰；按换水和动物状态处理，满{d['prime_interference_hours']}小时再复测。沙里发在这桶海水里读数偏低，仅供参考，用益尔复核。</li></ul>'''
    limits=[('NH3',f'≤{c["nh3_high"]:g}绿；高于{c["nh3_high"]:g}黄，测稀释样',f'0色绿；显色红，低于{d["animal_nh3_half_change_at"]:g}换1/3，达到{d["animal_nh3_half_change_at"]:g}换1/2并按规则加Prime'),('NO2',f'低于{c["no2_top"]:g}绿；顶格黄，稀释×{c["dilution_factor"]}','0绿；显色红'),('NO3','养水期不分档',f'≤{l["no3_green_max"]:g}绿；中间黄；≥{l["no3_red_min"]:g}红'),('KH',f'≥{l["kh"][1]:g}绿；{l["kh"][0]:g}–{l["kh"][1]:g}黄；低于{l["kh"][0]:g}红','同左'),('pH',f'≥{l["ph_min"]:g}绿；低于{l["ph_min"]:g}红','同左'),('盐度',f'{l["salinity_green"][0]}–{l["salinity_green"][1]}绿；外侧至{l["salinity_yellow"][0]}／{l["salinity_yellow"][1]}黄；其余红','同左'),('水温',f'{l["temperature_cycling_green"][0]}–{l["temperature_cycling_green"][1]}℃绿；外侧至{l["temperature_cycling_yellow"][0]}／{l["temperature_cycling_yellow"][1]}℃黄',f'{l["temperature_animals_green"][0]}–{l["temperature_animals_green"][1]}℃绿；外侧至{l["temperature_animals_yellow"][0]}／{l["temperature_animals_yellow"][1]}℃黄')]
    status='<div class="tw"><table><thead><tr><th>项目</th><th>养水期</th><th>有鱼／动物</th></tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+escape(s)+'</td>' for s in row)+'</tr>' for row in limits)+'</tbody></table></div>'
    nh3='<tr><td>NH3</td><td>益尔或沙里发（Salifert）</td><td>益尔暂填数字；沙里发按'+escape('、'.join(map(str,r['cards']['nh3_salifert'])))+'选格。测的是NH3＋NH4读数；沙里发在这桶海水里读数偏低，仅供参考，补氨与通过检查须益尔复核。</td></tr>'
    values={'daily_cycling_rules':daily,'cycle_check_rules':checks,'animal_nh3_rules':animal,'status_rules':status,'nh3_test_row':nh3,'no2_test_row':'<tr><td>NO2</td><td>益尔NO2试剂</td><td>色卡'+ '、'.join(map(str,r['cards']['no2']))+f'（mg/L）。最高格{c["no2_top"]:g}只能表示该值或更高；到顶测稀释样，读数×{c["dilution_factor"]}。通过线为{c["no2_pass"]:g}。</td></tr>','feed20':feed,'check20':check,'feed_factor':f(d['feed_ml_per_l']),'check_factor':f(d['check_ml_per_l']),'no2_pass':f(c['no2_pass']),'check_hours':str(c['check_hours']),'rounds_cn':{1:'一轮',2:'两轮',3:'三轮',4:'四轮'}.get(c['check_rounds'],str(c['check_rounds'])+'轮'),'kh_red':f(l['kh'][0]),'kh_green':f(l['kh'][1]),'ph_min':f(l['ph_min']),'nh3_lowest':escape(str(r['cards']['nh3_salifert'][0])),'low_buffer20':f'{20*c["low_buffer_change"][0]:g}–{20*c["low_buffer_change"][1]:g}','weekly20':f(20*d['weekly_change']),'no2_top':f(c['no2_top']),'dilution_factor':str(c['dilution_factor']),'no2_feed_below':f(c['no2_feed_below'])}
    for key,value in values.items():text=text.replace('{{'+key+'}}',value)
    if '{{' in text:raise ValueError('养护规则占位未替换')
    return text
